// 인증(Authentication) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const user = { email: "a@example.com", password: "pw123" };
const ok = user.email === "a@example.com" && user.password === "pw123";
console.log(ok ? "인증 성공" : "인증 실패");

// 인가(Authorization) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const user = { role: "editor" };
const canDelete = user.role === "admin";
console.log(canDelete ? "삭제 허용" : "삭제 거부");

// JWT 클레임 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const claims = { sub: "user-7", role: "admin", exp: 1893456000 };
console.log(claims.sub, claims.role);

// JWT 서명 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const data = "header.payload";
const sig = crypto.createHmac("sha256", "secret").update(data).digest("hex");
console.log(sig.length > 0);

// JWT 만료 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const token = { exp: Math.floor(Date.now() / 1000) + 60 };
const valid = token.exp > Math.floor(Date.now() / 1000);
console.log(valid);

// 액세스 토큰 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const header = "Bearer access-token";
const token = header.startsWith("Bearer ") ? header.slice(7) : null;
console.log(token);

// 리프레시 토큰 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
let refreshToken = "refresh-1";
function rotate(token) { return token === "refresh-1" ? "refresh-2" : null; }
console.log(rotate(refreshToken));

// OAuth 2.0 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const consent = { scope: "calendar.read", approved: true };
console.log(consent.approved && consent.scope.includes("read"));

// OAuth 플로우 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const appType = "spa";
const flow = appType === "spa" ? "authorization_code_pkce" : "client_credentials";
console.log(flow);

// OpenID Connect 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const idTokenClaims = { iss: "https://issuer", sub: "user-1", aud: "client-1" };
console.log(Boolean(idTokenClaims.iss && idTokenClaims.sub));

// SSO(Single Sign-On) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const session = { identityProvider: "company-idp", loggedIn: true };
const canUseMail = session.loggedIn;
console.log(canUseMail);

// SAML 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const assertion = { nameId: "user@example.com", issuer: "idp", signed: true };
console.log(assertion.signed && assertion.issuer === "idp");

// 세션 기반 인증 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const sessions = new Map([["sid1", { userId: 3 }]]);
const cookieSid = "sid1";
console.log(sessions.get(cookieSid).userId);

// 토큰 기반 인증 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const request = { headers: { authorization: "Bearer t1" } };
console.log(request.headers.authorization.includes("Bearer"));

// 비밀번호 해싱 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const hash = crypto.createHash("sha256").update("password").digest("hex");
console.log(hash !== "password");

// bcrypt 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const password = "pw";
const cost = 12;
console.log(`bcrypt는 ${password.length}글자 비밀번호를 cost ${cost}로 해시하도록 설정합니다.`);

// salt 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const salt = crypto.randomBytes(8).toString("hex");
console.log(salt.length);

// 레인보우 테이블 공격 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const table = new Map([["5f4dcc3b5aa765d61d8327deb882cf99", "password"]]);
console.log(table.has("unknown") ? "found" : "not found");

// 브루트 포스 공격 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const candidates = ["0000", "1234", "9999"];
const secret = "1234";
console.log(candidates.find(v => v === secret));

// 딕셔너리 공격 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const common = ["password", "qwerty", "letmein"];
const input = "letmein";
console.log(common.includes(input));

// 계정 잠금 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
let failures = 5;
const locked = failures >= 5;
console.log(locked ? "잠금" : "허용");

// MFA(다중 인증) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const factors = { password: true, otp: true };
console.log(factors.password && factors.otp ? "통과" : "거부");

// TOTP 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const timeStep = Math.floor(Date.now() / 30000);
const code = String(timeStep).slice(-6).padStart(6, "0");
console.log(code.length);

// FIDO2/WebAuthn 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const credential = { publicKeyStored: true, userVerified: true };
console.log(credential.publicKeyStored && credential.userVerified);

// RBAC(역할 기반 접근제어) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const permissions = { admin: ["delete"], viewer: ["read"] };
const role = "viewer";
console.log(permissions[role].includes("delete"));

// ABAC 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const ctx = { department: "sales", docDepartment: "sales", hour: 14 };
const allow = ctx.department === ctx.docDepartment && ctx.hour < 18;
console.log(allow);

// 권한 상승 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const user = { role: "user" };
const requestedRole = "admin";
console.log(user.role === "admin" && requestedRole === "admin");

// 최소 권한 원칙 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const needed = ["read:orders"];
const granted = ["read:orders"];
console.log(granted.every(p => needed.includes(p)));

// 제로 트러스트 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const request = { userOk: true, deviceOk: true, risk: "low" };
console.log(request.userOk && request.deviceOk && request.risk === "low");

// HTTPS 강제 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
function normalize(url) { return url.replace(/^http:/, "https:"); }
console.log(normalize("http://example.com"));

// HSTS 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const header = "max-age=31536000; includeSubDomains";
console.log(header.includes("max-age"));

// Content Security Policy 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const csp = "default-src 'self'; script-src 'self'";
console.log(csp.includes("script-src"));

// XSS 필터 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const input = "<script>alert(1)</script>";
const safe = input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
console.log(safe);

// CSRF 토큰 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const sessionToken = "abc123";
const formToken = "abc123";
console.log(sessionToken === formToken);

// 클릭재킹 방지 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const headers = { "x-frame-options": "DENY" };
console.log(headers["x-frame-options"] === "DENY");

// SQL 인젝션 방어 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const sql = "SELECT * FROM users WHERE email = ?";
const params = ["a@example.com"];
console.log(sql, params.length);

// 파라미터 바인딩 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const query = "UPDATE users SET name = ? WHERE id = ?";
const values = ["Ada", 1];
console.log({ query, values });

// 입력 소독(Sanitization) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const dirty = "<b>hi</b><script>x()</script>";
const clean = dirty.replace(/<script.*?<\/script>/g, "");
console.log(clean);

// 출력 인코딩 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const text = "<img src=x>";
const encoded = text.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
console.log(encoded);

// 보안 헤더 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const headers = { "content-security-policy": "default-src 'self'", "referrer-policy": "no-referrer" };
console.log(Object.keys(headers).length);

// OWASP Top 10 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const risks = ["Broken Access Control", "Injection", "Cryptographic Failures"];
console.log(risks.includes("Injection"));

// 취약점 스캔 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const findings = [{ severity: "high" }, { severity: "low" }];
console.log(findings.filter(f => f.severity === "high").length);

// 침투 테스트 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const scope = { allowed: ["app.example.com"], writtenPermission: true };
console.log(scope.writtenPermission && scope.allowed.length > 0);

// 공개키 암호화 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const { publicKey, privateKey } = crypto.generateKeyPairSync("rsa", { modulusLength: 1024 });
console.log(Boolean(publicKey && privateKey));

// 대칭키 암호화 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const key = "shared-secret";
const canDecrypt = key === "shared-secret";
console.log(canDecrypt);

// AES 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const algorithm = "aes-256-gcm";
console.log(algorithm.startsWith("aes"));

// RSA 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const pair = crypto.generateKeyPairSync("rsa", { modulusLength: 1024 });
console.log(pair.publicKey.type);

// 디지털 서명 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const message = "release-v1";
const signed = { message, signer: "private-key-owner" };
console.log(signed.message === message);

// PKI 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const pki = { ca: "Trusted CA", certIssued: true, revocationChecked: true };
console.log(pki.certIssued && pki.revocationChecked);

// 인증서 체인 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const chain = ["server", "intermediate", "root"];
console.log(chain[chain.length - 1] === "root");

// 환경 변수로 시크릿 관리 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
process.env.API_KEY = "demo-key";
console.log(process.env.API_KEY.startsWith("demo"));

// Vault 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const vault = new Map([["db/password", "secret"]]);
console.log(vault.has("db/password"));

// API 키 로테이션 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
let activeKeys = ["key-new", "key-old"];
activeKeys = activeKeys.filter(k => k !== "key-old");
console.log(activeKeys);

// 감사 로그(Audit Log) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const log = { actor: "admin", action: "delete_user", time: new Date().toISOString() };
console.log(`${log.actor}:${log.action}`);

// 세션 고정 공격 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
let sessionId = "attacker-known";
function login() { sessionId = "new-random-session"; return sessionId; }
console.log(login() !== "attacker-known");

// 세션 하이재킹 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const stolen = "sid-123";
const blockedSessions = new Set(["sid-123"]);
console.log(blockedSessions.has(stolen) ? "차단" : "허용");

// 쿠키 HttpOnly 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const cookie = "sid=abc; HttpOnly";
console.log(cookie.includes("HttpOnly"));

// 쿠키 Secure 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const cookie = "sid=abc; Secure";
console.log(cookie.endsWith("Secure"));

// SameSite 쿠키 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const cookie = "sid=abc; SameSite=Lax";
console.log(cookie.includes("SameSite=Lax"));

// CORS 화이트리스트 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const allow = new Set(["https://app.example.com"]);
const origin = "https://app.example.com";
console.log(allow.has(origin));

// IP 화이트리스트 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const allowed = ["203.0.113.10"];
const requestIp = "203.0.113.10";
console.log(allowed.includes(requestIp));

// 보안 코드 리뷰 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const change = { touchesAuth: true, reviewedBySecurity: true };
console.log(change.touchesAuth ? change.reviewedBySecurity : true);

// SAST 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const findings = ["hardcoded_secret", "unsafe_regex"];
console.log(findings.includes("hardcoded_secret"));

// DAST 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const response = { status: 200, headers: { "x-frame-options": "DENY" } };
console.log(response.status === 200 && Boolean(response.headers));

// 패스키(Passkey) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const passkey = { publicKeyRegistered: true, localUserVerified: true };
console.log(passkey.publicKeyRegistered && passkey.localUserVerified);

// PKCE(코드 교환 증명) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const crypto = require("crypto");
const verifier = "random-verifier";
const challenge = crypto.createHash("sha256").update(verifier).digest("base64url");
console.log(challenge.length > 0);

// 비밀번호 없는 인증(Passwordless) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const loginMethod = "magic_link";
const allowed = ["magic_link", "passkey", "otp"];
console.log(allowed.includes(loginMethod));

// 분산 세션 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const sharedStore = new Map();
sharedStore.set("sid", { userId: 1 });
console.log(sharedStore.get("sid").userId);

// 세션 클러스터링 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const nodes = [{ id: "a", sessions: 3 }, { id: "b", sessions: 3 }];
console.log(nodes.every(n => n.sessions === 3));

// 클라이언트 인증서(mTLS) 예시: Node.js에서 실행 가능한 안전한 시뮬레이션 코드
const mtls = { serverCertValid: true, clientCertValid: true };
console.log(mtls.serverCertValid && mtls.clientCertValid);
